import { createConsole } from "../../utils/Console.ts";
import {
  createServerMessage,
  MessageLike,
  ServerMessageOrMessageType,
} from "../ServerUtils.ts";
import {
  addEventListeners,
  removeEventListeners,
} from "../../utils/EventUtils.ts";
import BaseClient, { ServerURL } from "../BaseClient.ts";
import type * as ws from "ws";
import { Timer } from "../../utils/Timer.ts";
import {
  createWebSocketMessage,
  WebSocketMessageType,
  WebSocketMessageTypes,
  webSocketPingTimeout,
  webSocketReconnectTimeout,
  webSocketPingMessage,
  webSocketPongMessage,
} from "./WebSocketUtils.ts";
import { parseMessage } from "../../utils/ParseUtils.ts";

const _console = createConsole("WebSocketClient", { log: false });

class WebSocketClient extends BaseClient {
  static type = "webSocket" as const;
  readonly type = WebSocketClient.type;

  // WEBSOCKET
  #webSocket?: WebSocket;
  get webSocket() {
    return this.#webSocket;
  }
  set webSocket(newWebSocket) {
    if (this.#webSocket == newWebSocket) {
      _console.log("redundant webSocket assignment");
      return;
    }

    _console.log("assigning webSocket", newWebSocket);

    if (this.#webSocket) {
      removeEventListeners(this.#webSocket, this.#boundWebSocketEventListeners);
    }

    addEventListeners(newWebSocket, this.#boundWebSocketEventListeners);
    this.#webSocket = newWebSocket;

    _console.log("assigned webSocket");
  }
  get #readyState() {
    return this.webSocket?.readyState;
  }
  get isConnected() {
    return this.#readyState == WebSocket.OPEN;
  }
  get isDisconnected() {
    return this.#readyState == WebSocket.CLOSED;
  }

  url: URL | undefined;

  connect(
    url: string | URL = `${
      location.protocol.includes("https") ? "wss" : "ws"
    }://${location.host}`,
  ) {
    _console.log("connect", { url });

    if (this.webSocket) {
      this.assertDisconnection();
    }
    this._connectionStatus = "connecting";
    this.webSocket = new WebSocket(url);
  }

  disconnect() {
    _console.log("disconnect", { connectionStatus: this.connectionStatus });
    switch (this.connectionStatus) {
      case "connecting":
      case "connected":
        break;
      default:
        return;
    }

    if (this.isWaitingToReattemptConnection) {
      this.#clearReconnectTimeout();
    }

    if (this.webSocket && this.webSocket.readyState != WebSocket.CLOSED) {
      if (this.reconnectOnDisconnection) {
        this.reconnectOnDisconnection = false;
        this.webSocket.addEventListener(
          "close",
          () => {
            this.reconnectOnDisconnection = true;
          },
          { once: true },
        );
      }
      this._connectionStatus = "disconnecting";
      this.webSocket.close();
    } else {
      this._connectionStatus = "notConnected";
    }
  }

  reconnect() {
    this.assertDisconnection();
    this.connect(this.webSocket!.url);
  }

  toggleConnection(url?: ServerURL) {
    _console.log("toggleConnection", url, {
      connectionStatus: this.connectionStatus,
    });
    if (this.isConnected || this.connectionStatus == "connecting") {
      this.disconnect();
    } else if (url && this.webSocket?.url == url) {
      this.reconnect();
    } else {
      this.connect(url);
    }
  }

  // WEBSOCKET MESSAGING
  #sendMessage(message: MessageLike) {
    this.assertConnection();
    this.#webSocket!.send(message);
    this.#pingTimer.restart();
  }

  sendToServer(...messages: ServerMessageOrMessageType[]) {
    _console.log("sendToServer", messages);
    this.#sendMessage(
      createWebSocketMessage({
        type: "serverMessage",
        data: createServerMessage(...messages),
      }),
    );
  }

  // WEBSOCKET EVENTS
  #boundWebSocketEventListeners: {
    [K in keyof WebSocketEventMap]?: (event: any) => void;
  } = {
    open: this.#onWebSocketOpen.bind(this),
    message: this.#onWebSocketMessage.bind(this),
    close: this.#onWebSocketClose.bind(this),
    error: this.#onWebSocketError.bind(this),
  };

  #onWebSocketOpen(event: ws.Event) {
    _console.log("webSocket.open", event);
    this.#pingTimer.start();
    //this._connectionStatus = "connected";
    this.url = new URL(this.webSocket!.url);
    this._sendRequiredMessages();
  }
  async #onWebSocketMessage(event: ws.MessageEvent) {
    _console.log("webSocket.message", event);
    //this.#pingTimer.restart();
    //@ts-expect-error
    const arrayBuffer = await event.data.arrayBuffer();
    const dataView = new DataView(arrayBuffer);
    this.#parseWebSocketMessage(dataView);
  }
  #reconnectTimeout: ReturnType<typeof setTimeout> | undefined;
  #clearReconnectTimeout() {
    _console.log("#clearReconnectTimeout");
    if (this.#reconnectTimeout != undefined) {
      clearTimeout(this.#reconnectTimeout);
      this.#reconnectTimeout = undefined;
    }
    this._isWaitingToReattemptConnection = false;
  }
  #onWebSocketClose(event: ws.CloseEvent) {
    _console.log("webSocket.close", event);
    this.#onWebSocketClosed(event);
  }
  #onWebSocketError(event: ws.ErrorEvent) {
    _console.error("webSocket.error", event);
    this.#onWebSocketClosed(event);
  }

  #onWebSocketClosed(event: ws.CloseEvent | ws.ErrorEvent) {
    _console.log("onWebSocketClosed", event, {
      connectionStatus: this.connectionStatus,
    });

    if (this._connectionStatus == "notConnected") {
      return;
    }

    this.#pingTimer.stop();
    if (this.reconnectOnDisconnection) {
      this.#clearReconnectTimeout();
      this._isWaitingToReattemptConnection = true;
      this.#reconnectTimeout = setTimeout(() => {
        this._isWaitingToReattemptConnection = false;
        if (this.reconnectOnDisconnection) {
          this.reconnect();
        }
      }, webSocketReconnectTimeout);
    }

    this._connectionStatus = "notConnected";
  }

  // PARSING
  #parseWebSocketMessage(dataView: DataView<ArrayBuffer>) {
    parseMessage(
      dataView,
      WebSocketMessageTypes,
      this.#onServerMessage.bind(this),
      null,
      true,
    );
  }

  #onServerMessage(
    messageType: WebSocketMessageType,
    dataView: DataView<ArrayBuffer>,
  ) {
    switch (messageType) {
      case "ping":
        this.#pong();
        break;
      case "pong":
        break;
      case "serverMessage":
        this.parseMessage(dataView);
        break;
      default:
        _console.error(`uncaught messageType "${messageType}"`);
        break;
    }
  }

  // PING
  #pingTimer = new Timer(this.#ping.bind(this), webSocketPingTimeout);
  #ping() {
    this.#sendMessage(webSocketPingMessage);
  }
  #pong() {
    this.#sendMessage(webSocketPongMessage);
  }
}

export default WebSocketClient;
